// Chuẩn bị nội dung cho từng kênh từ bài vừa đăng Fanpage
// Tiêu đề = DÒNG đầu tiên; mô tả = dòng kế tiếp (vẫn có trong thân bài); thân bài = từ dòng 2 trở đi
// Ảnh cho Zalo: cột "Ảnh Zalo" (nếu có) thay ảnh chính; ảnh thêm gắn #fb chỉ dùng cho Fanpage, #zalo chỉ dùng cho Zalo
const p = $('Khi được gọi').first().json;
const full = String(p.noiDung || '').replace(/\r/g, '').trim();
const cut = full.indexOf('---***---');
const than = cut >= 0 ? full.slice(0, cut) : full;
const footer = cut >= 0 ? full.slice(cut + 9) : '';
const lines = (s) => String(s).split('\n').map(x => x.trim()).filter(Boolean);
const MK = /^\[\s*(?:ảnh|anh|hình|hinh)\s*([0-9][0-9 ,+&và]*)\]$/iu;   // dòng đánh dấu [ảnh 2] / [ảnh 2, 3]
const soMK = (l) => { const m = String(l || '').trim().match(MK); return m ? m[1].split(/[^0-9]+/).filter(Boolean).map(Number) : null; };
const boMK = (s) => String(s || '').split('\n').filter(l => !soMK(l)).join('\n').replace(/\n{3,}/g, '\n\n');
const L = lines(than);
// Ảnh đánh số như ảnh lưới: ảnh 1 = ảnh chính, ảnh 2.. = cột Ảnh thêm theo thứ tự (kể cả ảnh #fb)
const KR = String(p.anhThem || '').split('\n').map(s => s.trim()).filter(Boolean);
const daDanh = new Set(); L.forEach(l => (soMK(l) || []).forEach(k => { if (k >= 2) daDanh.add(k - 2); }));
const title = (L[0] || `Bài #${p.id}`).replace(/\s+/g, ' ').slice(0, 150);
// bỏ dòng đánh dấu khỏi chữ, nhớ vị trí: truoc[i] = các số ảnh chèn trước dòng rest[i]
let rest = [], truoc = {};
for (const l of L.slice(1)) { const s = soMK(l); if (s) (truoc[rest.length] = truoc[rest.length] || []).push(...s); else rest.push(l); }
let desc = '';
const boDong0 = () => { const t = {}; for (const [k, v] of Object.entries(truoc)) { const j = Math.max(0, Number(k) - 1); (t[j] = t[j] || []).push(...v); } truoc = t; };
if (rest[0] && rest[0].length <= 290) { desc = rest[0]; }   // dòng 2 = mô tả OA và VẪN giữ trong thân bài (quản lý yêu cầu 15/11)
else if (rest[0]) { const s = rest[0].slice(0, 280); desc = s.slice(0, Math.max(s.lastIndexOf(' '), 200)) + '…'; }
const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const sach = (u) => String(u || '').trim().replace(/#(fb|zalo|tay|src=[a-z0-9]+)$/i, '');
const anhChinh = sach(p.anhZalo) || sach(p.linkAnh);
const anhThem = KR.filter((s, i) => !/#fb$/i.test(s) && !daDanh.has(i)).map(sach).filter(Boolean);   // ảnh chưa đánh dấu -> AI / tự xếp
// Đặt ảnh: AI nhìn ảnh và chọn ý phù hợp -> ảnh ngay dưới ý đó; AI lỗi mà số ảnh = số ý -> lần lượt dưới từng ý; ảnh còn lại -> cuối bài
const laY = (l) => /^(?:[^\p{L}\p{N}\s]+\s*)?([0-9]️?⃣|🔟|\d{1,2}[.)]\s)/u.test(l); // cho phép emoji đứng trước số (🔥 1️⃣ …)
const yIdx = rest.map((l, i) => laY(l) ? i : -1).filter(i => i >= 0);
let gan = null;   // gan[i] = thứ tự ý (0..) của ảnh thêm i, -1 = cuối bài
try { if ($('AI xếp ảnh theo ý').isExecuted) {
  const t = (($('AI xếp ảnh theo ý').first().json.candidates || [])[0]?.content?.parts || []).map(x => x.text || '').join('');
  const v = JSON.parse(t); gan = anhThem.map(() => -1); const dung = new Set();
  for (const x of v.xep || []) { const a = Number(x.anh) - 1, k = Number(x.y) - 1;
    if (a >= 0 && a < anhThem.length && k >= 0 && k < yIdx.length && !dung.has(k) && gan[a] < 0) { gan[a] = k; dung.add(k); } }
} } catch (e) { gan = null; }
if (!gan && anhThem.length && yIdx.length === anhThem.length) gan = anhThem.map((_, i) => i);
// AI không chạy/lỗi: chia đều ảnh cho các ý (mỗi ý tối đa 1 ảnh, dư thì cuối bài)
if (!gan && anhThem.length && yIdx.length) gan = anhThem.map((_, a) => a < yIdx.length ? (anhThem.length <= yIdx.length ? Math.floor(a * yIdx.length / anhThem.length) : a) : -1);
if (!gan) gan = anhThem.map(() => -1);
// Bài không có ý đánh số: rải ảnh đều giữa bài, đặt ngay trước các dòng tiêu đề mục (dòng kết thúc bằng ? hoặc không có dấu chấm, hoặc viết hoa)
let raiDeu = null;
if (!yIdx.length && anhThem.length && rest.length >= 3) {
  const hoaT = (s) => { const c = s.replace(/[^\p{L}]/gu, ''); return c.length >= 8 && c === c.toUpperCase(); };
  const tieuDeMuc = (s) => s && (/[?:]$/.test(s) || hoaT(s) || (s.length <= 90 && !/[.!…]$/.test(s)));
  const moc = []; for (let i = 1; i < rest.length - 1; i++) if (tieuDeMuc(rest[i + 1]) && !tieuDeMuc(rest[i])) moc.push(i);
  raiDeu = {}; const daDung = new Set();
  anhThem.forEach((u, a) => {
    let i = Math.min(rest.length - 2, Math.round((a + 1) * rest.length / (anhThem.length + 1)) - 1);
    const conLai = moc.filter(m => !daDung.has(m));
    if (conLai.length) { i = conLai.reduce((b, m) => Math.abs(m - i) < Math.abs(b - i) ? m : b, conLai[0]); daDung.add(i); }
    (raiDeu[i] = raiDeu[i] || []).push(a); gan[a] = -2;
  });
}
const pa1 = gan.some(k => k >= 0);
const body = [];
const coMK1 = Object.values(truoc).some(v => v.includes(1));
// đã đánh dấu [ảnh N] thì luôn chèn, kể cả ảnh bìa / ảnh #fb (yêu cầu 16/11: ảnh bìa dùng lại trong bài được)
const anhSo = (k) => k === 1 ? anhChinh : (KR[k - 2] ? sach(KR[k - 2]) : '');
const daChen = new Set();
const chenMK = (i) => (truoc[i] || []).forEach(k => { const u = anhSo(k); if (u && !daChen.has(u)) { daChen.add(u); body.push({ type: 'image', url: u }); } });
if (anhChinh && !coMK1) body.push({ type: 'image', url: anhChinh });
let dangY = -1, dauKhoiEmoji = false;
rest.forEach((l, i) => {
  chenMK(i);
  body.push({ type: 'text', content: '<p>' + esc(l) + '</p>' });
  if (raiDeu && raiDeu[i]) raiDeu[i].forEach(a => body.push({ type: 'image', url: anhThem[a] }));
  if (!pa1) return;
  const k = yIdx.indexOf(i);
  if (k >= 0) dangY = k;
  const sau = rest[i + 1];
  if (k >= 0) { dauKhoiEmoji = sau ? !/^[\p{L}\p{N}"“'(]/u.test(sau) : false; return; }
  // hết khối của ý: dòng sau là ý mới / hết bài; với ý cuối: dòng sau là tiêu đề viết hoa, hoặc (khi gạch đầu dòng là chữ) dòng sau bắt đầu bằng emoji
  const hoa = (s) => { const c = s.replace(/[^\p{L}]/gu, ''); return c.length >= 8 && c === c.toUpperCase(); };
  const hetKhoi = dangY >= 0 && (!sau || laY(sau) || hoa(sau) || (!dauKhoiEmoji && !/^[\p{L}\p{N}"“'(]/u.test(sau)));
  if (hetKhoi) { gan.forEach((k, a) => { if (k === dangY) body.push({ type: 'image', url: anhThem[a] }); }); dangY = -1; }
});
chenMK(rest.length);
gan.forEach((k, a) => { if (k === -1) body.push({ type: 'image', url: anhThem[a] }); });
if (footer.trim()) for (const l of lines('---***---\n' + footer)) body.push({ type: 'text', content: '<p>' + esc(l) + '</p>' });
const article = { type: 'normal', title, author: 'GOS Academy', description: desc || title, body, status: 'show', comment: 'show',
  ...(anhChinh ? { cover: { cover_type: 'photo', photo_url: anhChinh, status: 'show' } } : {}) };
const note = String(p.note || '');
const daOA = /\[OA✓\]|Zalo OA OK/.test(note);
const daGMF = /\[GMF✓\]|nhóm GMF OK/.test(note);
if (daOA && daGMF) return []; // đã đăng đủ mọi kênh -> không làm gì
return [{ json: { ...p, noiDung: boMK(full), linkAnh: anhChinh, anhThem: anhThem.join('\n'), title, article, daOA, daGMF, cachDatAnh: (daChen.size ? `${daChen.size} ảnh theo đánh dấu [ảnh N]` + (anhThem.length ? ', ' : '') : '') + (anhThem.length ? (raiDeu ? `${anhThem.length} ảnh rải đều giữa bài` : `${gan.filter(k => k >= 0).length} ảnh dưới ý, ${gan.filter(k => k < 0).length} ảnh cuối bài`) : '') } }];

function oaRes() { for (const nm of ['Zalo OA: thử lại', 'Zalo OA: đăng bài viết']) { try { if ($(nm).isExecuted) return $(nm).first().json; } catch (e) {} } return null; }
// Tin gửi vào nhóm GMF: ảnh + nội dung bài + link Fanpage
const p = $('Chuẩn bị bài').first().json;
let att = null;
for (const nm of ['Zalo: tải ảnh lên (thử lại)', 'Zalo: tải ảnh lên']) { try { if (!att && $(nm).isExecuted) att = $(nm).first().json.data?.attachment_id || null; } catch (e) {} }
const oa = oaRes();
const oaTruoc = !!p.daOA;
const oaOk = oaTruoc || (oa && oa.error === 0);
// Link bài Zalo OA: hỏi Zalo id bài vừa tạo (token chỉ sống vài phút), không được thì tìm theo tiêu đề trong các bài mới nhất
const OA = '<ZALO_OA_ID>';
const at = $('Lấy token Zalo').first().json.access_token;
let oaLink = '';
const tok = oa && oa.error === 0 ? oa.data?.token : '';
for (let i = 0; tok && !oaLink && i < 4; i++) {
  try {
    const r = await this.helpers.httpRequest({ method: 'POST', url: 'https://openapi.zalo.me/v2.0/article/verify', headers: { access_token: at }, body: { token: tok }, json: true });
    if (r?.data?.id) oaLink = `https://post.oa.zalo.me/d/${OA}?id=${r.data.id}&pageId=${OA}`;
  } catch (e) {}
  if (!oaLink) await new Promise(res => setTimeout(res, 3000));
}
if (!oaLink && oaOk) {
  try {
    const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://openapi.zalo.me/v2.0/article/getslice?offset=0&limit=10&type=normal', headers: { access_token: at }, json: true });
    const m = (r?.data?.medias || []).find(x => String(x.title || '').trim() === String(p.title || '').trim());
    if (m) oaLink = m.link_view;
  } catch (e) {}
}
const gio = DateTime.now().setZone('Asia/Ho_Chi_Minh').toFormat('HH:mm dd/MM/yyyy');
const head = `✅ ĐÃ ĐĂNG BÀI #${p.id} lúc ${gio}\n📝 ${String(p.title || '').slice(0, 150)}`
  + `\n🔗 Fanpage: ${p.linkFb || '(chưa có link)'}`
  + `\n🔗 Zalo OA: ${oaLink || (oaOk ? 'đã đăng (chưa lấy được link, xem trên trang OA)' : '❌ chưa đăng được')}`;
// nhiều ảnh: thay ảnh chính bằng 1 ảnh lưới đánh số (ảnh 1 = ảnh chính)
let soAnh = 1; try { if ($('Ghép ảnh xem').isExecuted) { const g = $('Ghép ảnh xem').first().json; if (g.attachment_id) { att = g.attachment_id; soAnh = g.soAnh || 1; } } } catch (e) {}
const msgs = [att ? { text: head + (soAnh > 1 ? `\n🖼️ Bài có ${soAnh} ảnh (số trên ảnh = thứ tự)` : ''), attachment: { type: 'template', payload: { template_type: 'media', elements: [{ media_type: 'image', attachment_id: att }] } } } : { text: head }];
// ảnh thêm của bài (1 bài nhiều ảnh)
const max = 1900; let cur = '';
for (const para of String(p.noiDung || '').split(/\n{2,}/)) {
  const j = cur ? cur + '\n\n' + para : para;
  if (j.length <= max) { cur = j; continue; }
  if (cur) msgs.push({ text: cur });
  cur = para.length <= max ? para : '';
  if (para.length > max) for (let i = 0; i < para.length; i += max) msgs.push({ text: para.slice(i, i + max) });
}
if (cur) msgs.push({ text: cur });
msgs.push({ text: `📊 Kết quả bài #${p.id}:\n• Fanpage: ✅\n• Zalo OA (bài viết): ${oaTruoc ? '✅ (đã đăng trước đó)' : oaOk ? '✅' : '❌ ' + String(oa?.message || oa?.error?.message || 'lỗi').slice(0, 120)}\n• Nhóm Zalo: ✅` });
return msgs.map(message => ({ json: { message, oaOk, oaLoi: oaOk ? '' : String(oa?.message || oa?.error?.message || 'lỗi').slice(0, 120) } }));

function oaRes() { for (const nm of ['Zalo OA: thử lại', 'Zalo OA: đăng bài viết']) { try { if ($(nm).isExecuted) return $(nm).first().json; } catch (e) {} } return null; }
// Tổng hợp kết quả từng kênh -> ghi chú (kèm dấu kênh đã đăng)
const p = $('Chuẩn bị bài').first().json;
const r = oaRes(); const oaRun = !!r; const oaOk = oaRun && r.error === 0;
const oaLoi = oaRun && !oaOk ? String(r.message || r.error?.message || 'lỗi').slice(0, 120) : '';
let gRun = false, gOk = false, gLoi = '';
try { if ($('Lọc tin lỗi').isExecuted) { gRun = true; gOk = $('Lọc tin lỗi').first().json.loi === 0; gLoi = $('Lọc tin lỗi').first().json.lyDo; } } catch (e) {}
try { if ($('Gửi lại vào nhóm').isExecuted) { const a = $('Gửi lại vào nhóm').all(); gOk = a.every(i => i.json && i.json.error === 0);
  const l = a.find(i => !(i.json && i.json.error === 0)); gLoi = l ? String(l.json.message || l.json.error?.message || 'lỗi').slice(0, 120) : ''; } } catch (e) {}
const parts = [], loi = [];
if (oaRun) { parts.push(oaOk ? '[OA✓]' : 'Zalo OA lỗi (' + oaLoi + ')'); if (!oaOk) loi.push('Zalo OA lỗi (' + oaLoi + ')'); }
if (gRun) { parts.push(gOk ? '[GMF✓]' : 'nhóm GMF lỗi (' + gLoi + ')'); if (!gOk) loi.push('nhóm GMF lỗi (' + gLoi + ')'); }
const t = $now.setZone('Asia/Ho_Chi_Minh').toFormat('dd/MM HH:mm');
const note = [String(p.note || '').trim(), 'Đăng chéo ' + t + ': ' + parts.join(' ')].filter(Boolean).join(' | ');
return [{ json: { id: String(p.id), note, loi: loi.join(', ') } }];

// Tin nào gửi vào nhóm chưa thành công
const sent = $input.all(); const msgs = $('Soạn tin nhóm').all();
const failed = msgs.filter((m, i) => !(sent[i] && sent[i].json && sent[i].json.error === 0)).map(m => m.json.message);
const loi = sent.find(s => !(s.json && s.json.error === 0));
return [{ json: { loi: failed.length, msgs: failed, lyDo: loi ? String(loi.json.message || loi.json.error?.message || 'lỗi').slice(0, 120) : '' } }];

// Hai bản: 'nen' để làm nền mờ, 'fg' đặt nguyên ở giữa
const b = $input.first().binary || {};
if (!b.data) return [{ json: { loi: 'không có ảnh' } }];
return [{ json: {}, binary: { nen: b.data, fg: b.data } }];

// Gắn ảnh bìa 16:9 vào bài OA: ưu tiên ảnh ngang đã tạo, không có thì ảnh vuông + nền mờ, lỗi nữa thì ảnh gốc
const p = $('Chuẩn bị bài').first().json;
let url = String(p.anhBia || '').trim().replace(/#(src=[a-z0-9]+|tay|fb|zalo)$/i, '');   // bỏ nhãn #tay/#src= (Zalo không tải được link có nhãn)   // ảnh ngang 16:9 AI đã tạo lúc duyệt / lệnh /anhbia
if (!url) try { const imgs = $('Lấy link ảnh bìa').first().json.images || []; url = (imgs.sort((a, b) => b.width - a.width)[0] || {}).source || ''; } catch (e) {}
const article = { ...p.article };
if (url) article.cover = { cover_type: 'photo', photo_url: url, status: 'show' };
return [{ json: { ...p, article, anhBiaNguon: p.anhBia ? 'ảnh ngang AI' : url ? 'nền mờ' : 'ảnh gốc' } }];

// Ảnh chính + ảnh thêm cho Zalo -> 1 ảnh lưới có số (Zalo chỉ hiện 1 ảnh mỗi tin)
const p = $('Chuẩn bị bài').first().json;
const them = String(p.anhThem || '').split('\n').map(s => s.trim()).filter(Boolean);
return [{ json: { urls: [p.linkAnh, ...them].filter(Boolean), oa_id: $('Khi được gọi').first().json.oa_id } }];

// Chuẩn bị cho AI xếp ảnh: danh sách ý đánh số của bài + ảnh thêm dùng cho Zalo (tải về, gửi kèm cho AI nhìn)
const p = $('Khi được gọi').first().json;
const full = String(p.noiDung || '').replace(/\r/g, '');
const than = full.split('---***---')[0];
const MK = /^\[\s*(?:ảnh|anh|hình|hinh)\s*([0-9][0-9 ,+&và]*)\]$/iu;   // dòng đánh dấu [ảnh 2] / [ảnh 2, 3]
const soMK = (l) => { const m = String(l || '').trim().match(MK); return m ? m[1].split(/[^0-9]+/).filter(Boolean).map(Number) : null; };
const boMK = (s) => String(s || '').split('\n').filter(l => !soMK(l)).join('\n').replace(/\n{3,}/g, '\n\n');
const L0 = than.split('\n').map(x => x.trim()).filter(Boolean).slice(1);
const daDanh = new Set(); L0.forEach(l => (soMK(l) || []).forEach(k => { if (k >= 2) daDanh.add(k - 2); }));
const L = L0.filter(l => !soMK(l));
const laY = (l) => /^(?:[^\p{L}\p{N}\s]+\s*)?([0-9]️?⃣|🔟|\d{1,2}[.)]\s)/u.test(l); // cho phép emoji đứng trước số (🔥 1️⃣ …)
const y = [];
L.forEach((l, i) => { if (laY(l)) y.push(l + (L[i + 1] && !laY(L[i + 1]) ? ' – ' + L[i + 1] : '')); });
const sach = (u) => String(u || '').trim().replace(/#(fb|zalo|tay|src=[a-z0-9]+)$/i, '');
const them = String(p.anhThem || '').split('\n').map(s => s.trim()).filter(Boolean).filter((s, i) => !/#fb$/i.test(s) && !daDanh.has(i)).map(sach).filter(Boolean);
if (!them.length || !y.length) return [{ json: { canXep: false } }];
const parts = [{ text: 'Bài viết có các ý đánh số sau:\n' + y.map((t, i) => `Ý ${i + 1}: ${t.slice(0, 220)}`).join('\n')
  + `\n\nDưới đây là ${them.length} ảnh minh họa (Ảnh 1..${them.length}). Với MỖI ảnh, chọn số ý mà ảnh minh họa rõ nhất (dựa vào chữ và hình trong ảnh). Nếu ảnh là ảnh tổng quan / không khớp riêng ý nào thì y = 0. Mỗi ý chỉ nhận tối đa 1 ảnh.` }];
for (const [i, u] of them.entries()) {
  try {
    const b = Buffer.from(await this.helpers.httpRequest({ method: 'GET', url: u, encoding: 'arraybuffer', json: false }));
    parts.push({ text: `Ảnh ${i + 1}:` }, { inlineData: { mimeType: 'image/jpeg', data: b.toString('base64') } });
  } catch (e) { parts.push({ text: `Ảnh ${i + 1}: (không tải được)` }); }
}
const body = { contents: [{ parts }], generationConfig: { responseMimeType: 'application/json',
  responseSchema: { type: 'OBJECT', properties: { xep: { type: 'ARRAY', items: { type: 'OBJECT', properties: { anh: { type: 'INTEGER' }, y: { type: 'INTEGER' } }, required: ['anh', 'y'] } } }, required: ['xep'] } } };
return [{ json: { canXep: true, soY: y.length, soAnh: them.length, body } }];
